// 女主角给爸爸打电话（语音，50 段）。">" = 爸爸，无标记 = 她。
[
  { title: "爸爸给手机AI取名", mood: { name: "老李在线", emo: "happy", pts: 2, min: 150 },
    lines: ["爸，你手机里那个AI好用吗？", ">好用，我给它取名叫老李。", "为什么叫老李？", ">它回答问题总要想半天，像老李。", "那它抢不了我饭碗。", ">抢也是先抢老李的。"] },
  { title: "爸爸把闹钟改成鱼咬钩", mood: { name: "鱼咬钩了", emo: "playful", pts: 2, min: 120 },
    lines: [">你猜我闹钟铃声是啥？", "是不是《东方红》？", ">不，是鱼咬钩的声音。", "这你哪儿下载的？", ">我自己录的，对着水盆。", "所以早上起来是被水盆叫醒的。", ">它比你妈温柔。"] },
  { title: "爸爸输给了手机象棋", mood: { name: "不服气", emo: "playful", pts: 2, min: 120 },
    lines: [">不跟你说了，我正跟手机下棋呢。", "赢了吗？", ">它让我三步，我还输了。", "那你怎么不换个简单的？", ">简单的它不让我赢，说我欺负它。", "爸，它是真的在哄你。"] },
  { title: "爸爸的保温杯泡了咖啡", mood: { name: "咖啡续命", emo: "energized", pts: 2, min: 180 },
    lines: [">你说的那个冰美式，我试了。", "你喝了？", ">泡在保温杯里，加了两颗枸杞。", "爸，那是对咖啡的侮辱。", ">我今天走了两万步，没停。", "那这杯确实算续命。"] },
  { title: "爸爸说周一是人发明的", mood: { name: "周一免疫", emo: "happy", pts: 2, min: 150 },
    lines: [">早饭吃了吗？", "还没，今天周一，不太想出门。", ">找点现成的先吃，别拖着。", "好，我吃完再说。"] },
  { title: "爸爸安排了象棋相亲", mood: { name: "棋逢对手", emo: "playful", pts: 2, min: 120 },
    lines: [">老张家有个孩子，跟你同岁。", "爸，又相亲？", ">不是相亲，是下棋。", "跟谁下？", ">跟他，我下输给他十年了。", "所以我是去替你报仇的？", ">嗯，顺便认识认识。"] },
  { title: "爸爸被长辈群刷屏了", mood: { name: "群消息99+", emo: "happy", pts: 2, min: 120 },
    lines: [">你们那种群，消息多吗？", "我有个群，99+，不敢点。", ">我也有，是老年大学的。", "你怎么处理？", ">我就挑最长的点赞。", "爸，你这招比我强。"] },
  { title: "爸爸回了三个嗯", mood: { name: "已读不回", emo: "playful", pts: 2, min: 90 },
    lines: ["爸，我发你那么长一段话。", ">收到了。", "你就回了个‘嗯’。", ">三个，嗯嗯嗯。", "这算已读不回吗？", ">算已读，也回了，算三倍。"] },
  { title: "爸爸看懂了体检单", mood: { name: "指标正常", emo: "happy", pts: 2, min: 150 },
    lines: [">你那体检单，我替你看了。", "爸，那是我的隐私。", ">没事，我就看了看尿酸。", "怎么样？", ">比我低，我心里舒坦了。", "你到底是关心我还是比较我。", ">都有，吃了没？"] },
  { title: "我的存款被爸爸查岗", mood: { name: "以前有过", emo: "playful", pts: 1, min: 90 },
    lines: [">你现在存款有多少？", "爸，有过，后来都去哪儿了呢。", ">去哪儿了？", "外卖、房租、咖啡。", ">那它们是不是都挺好的？", "挺好的，都比我过得好。"] },
  { title: "爸爸远程验房", mood: { name: "房东怕我", emo: "confident", pts: 2, min: 150 },
    lines: ["爸，房东说墙面不能钉钉子。", ">你问他，是承重墙吗？", "他说不是。", ">那你告诉他，你爸是修东西的。", "他听完说随便钉。", ">这叫不战而屈人之兵。"] },
  { title: "隔壁老张儿子上岸了", mood: { name: "上岸亲戚", emo: "happy", pts: 2, min: 120 },
    lines: [">老张儿子考上编制了。", "恭喜他。", ">你要不要也考？", "爸，我数学是体育老师教的。", ">那就别考了，爸养你。", "你别说，我有点心动。"] },
  { title: "加班到明天才下班", mood: { name: "打工人傲气", emo: "playful", pts: 2, min: 150 },
    lines: [">你那边还没忙完？", "还剩一点，今晚估计得晚点。", ">晚点也得吃饭啊。", "嗯，刚吃过，您先睡，别等我。"] },
  { title: "信用卡账单当奖状", mood: { name: "账单勋章", emo: "happy", pts: 2, min: 120 },
    lines: [">你给我发的那个红纸片是什么？", "是信用卡账单。", ">金额那么大，我还以为是奖状。", "在某种意义上，是我努力的证明。", ">那我给你贴墙上？", "爸，别，贴了我就还不上了。"] },
  { title: "爸爸想卖自己钓的鱼", mood: { name: "副业启动", emo: "energized", pts: 2, min: 180 },
    lines: [">我打算搞个副业。", "什么副业？", ">卖鱼，我已经想好了名字。", "叫什么？", ">‘老爸亲钓’，一条十块。", "你一年钓三条，能养活谁？", ">所以才是限量款。"] },
  { title: "爸爸舍不得扔旧螺丝", mood: { name: "断舍离失败", emo: "inspired", pts: 2, min: 150 },
    lines: ["爸，我最近在断舍离。", ">什么叫断舍离？", "就是不需要的东西，狠心扔掉。", ">那我抽屉里三百颗螺丝呢？", "那是需要的吗？", ">不需要，但是它们认识我。"] },
  { title: "爸爸要带走一把扳手", mood: { name: "搬家带宝", emo: "energized", pts: 2, min: 180 },
    lines: ["爸，我下周要搬家了。", ">搬！我帮你想想带什么。", "衣服，电脑，锅。", ">还有扳手，必须带一把。", "我没有扳手。", ">那我寄你一把，三十年的老伙计。", "行吧，家里第一件传家宝。"] },
  { title: "爸爸问同事八卦", mood: { name: "吃瓜爸爸", emo: "happy", pts: 2, min: 120 },
    lines: ["爸，我们组里有个同事天天迟到。", ">然后呢？", "然后老板居然夸他有个性。", ">后来呢，后来呢？", "后来……就没后来了。", ">你这个故事不完整，我睡不着了。"] },
  { title: "我鼓起勇气打了预约电话", mood: { name: "社恐通关", emo: "confident", pts: 3, min: 240 },
    lines: ["爸，我今天给牙科打电话预约了。", ">你不是最怕打电话吗？", "我对着墙练了三遍。", ">厉害，比我当年强。", "你当年怎么样？", ">我当年给你妈打电话，打错了三次。"] },
  { title: "爸爸催我早睡", mood: { name: "彼此彼此", emo: "playful", pts: 2, min: 120 },
    lines: [">都几点了还不睡？", "爸，现在凌晨一点半。", ">所以我问你。", "那你为什么也没睡？", ">我……起来喝水。", ">好了，你快睡，我也去睡。"] },
  { title: "爸爸的语音变成了相声", mood: { name: "六十秒相声", emo: "happy", pts: 2, min: 150 },
    lines: ["爸，你那条语音，我听了五遍。", ">怎么了，听不懂？", "你前半段在骂手机，后半段在夸手机。", ">前半段它不听话。", "后半段呢？", ">后半段它听话了。"] },
  { title: "爸爸遛弯遇上了领导", mood: { name: "巧遇领导", emo: "happy", pts: 2, min: 120 },
    lines: [">我今天在广场遇到你们老板了。", "什么？你认识我老板？", ">不认识，他在跳舞，我鼓了掌。", "你怎么知道是他？", ">他舞跳得和你周报一样，认真。", "爸，你从哪儿看过我周报？"] },
  { title: "爸爸教我棋局式职场", mood: { name: "步步为营", emo: "inspired", pts: 2, min: 180 },
    lines: ["爸，我领导总让我背锅。", ">象棋里有个子叫‘卒’。", "我就是那颗卒？", ">卒过了河，就不能后退了。", "所以我要往前冲？", ">不，你可以把锅传给‘炮’。"] },
  { title: "爸爸往可乐里泡枸杞", mood: { name: "养生新流派", emo: "playful", pts: 2, min: 120 },
    lines: [">我发明了一种养生茶。", "什么茶？", ">可乐加枸杞，叫‘可杞’。", "爸，这不对。", ">对啊，甜的，还补肾。", "我觉得你可以申请专利。"] },
  { title: "爸爸和音箱吵了一架", mood: { name: "人机大战", emo: "happy", pts: 2, min: 150 },
    lines: [">那个小音箱，今天又听错我话了。", "你让它干嘛？", ">我说放《空城计》，它放了《空城》。", "那还挺接近的。", ">我说你错了，它说‘对不起’。", ">我气没消，它倒先认错了。"] },
  { title: "爸爸第一次扫码付款", mood: { name: "扫码成功", emo: "energized", pts: 2, min: 150 },
    lines: [">今天菜市场我扫码了！", "真的？成功了吗？", ">成功，就是摊主说我扫的是他的身份证。", "……那你付了多少？", ">三块，他说请我吃葱。", "所以最后赚了葱？", ">赚了。"] },
  { title: "我撒娇要红烧肉", mood: { name: "撒娇成功", emo: "flirty", pts: 2, min: 150 },
    lines: ["爸，我好久没吃你做的红烧肉了。", ">你想吃就回来。", "我不回，我就想你寄过来。", ">寄过来都凉了，你让我怎么办。", "那你就把锅寄过来。", ">好，我先去买个大点的箱子。"] },
  { title: "爸爸的鱼被猫叼走了", mood: { name: "鱼去猫腹", emo: "playful", pts: 2, min: 120 },
    lines: [">今天钓了一条大的。", "多大？", ">这么大。", "爸，我听不见这么大。", ">三斤二两，结果被猫叼走了。", "猫比你钓鱼还强。"] },
  { title: "爸爸夸我像他年轻时", mood: { name: "像爸爸", emo: "flirty", pts: 2, min: 120 },
    lines: [">你妈今天又夸你了。", "夸我什么？", ">说你眼睛像我，嘴巴也像。", "那我是不是也聪明？", ">不是，聪明像你妈。", "爸，你这是谦虚还是挖苦自己。", ">是实话。"] },
  { title: "爸爸问我想家吗", mood: { name: "想家了", emo: "sad", pts: 2, min: 240 },
    lines: [">最近天凉了，你多穿点。", "嗯，我知道。", ">你房间窗台上，那盆花开了。", "真的？", ">开了，我每天给它浇水。", "那你替我多看它两眼。"] },
  { title: "出租屋夜里的一通电话", mood: { name: "夜里发空", emo: "sad", pts: 3, min: 270 },
    lines: [">怎么啦，这会儿打来？", "没啥事，问你睡了没。", ">还没，正准备关灯。", "哦，那我也不多说了，晚安，爸。"] },
  { title: "过年回不回家的纠结", mood: { name: "回家难题", emo: "sad", pts: 2, min: 240 },
    lines: [">过年回来吗？", "爸，公司可能要值班。", ">哦，值班啊。", "我再看看能不能调休。", ">不用调，你忙你的。", ">家里一直留着你的碗。"] },
  { title: "爸爸把我的房间擦干净了", mood: { name: "空房间", emo: "sad", pts: 2, min: 210 },
    lines: [">今天我把你房间擦了一遍。", "辛苦了，爸。", ">你书桌上那只旧笔，我没丢。", "留着吧，那是我初中的。", ">嗯。屋里太安静了。", "爸，下个月我回去。"] },
  { title: "爸爸又让我考个证", mood: { name: "被唠叨了", emo: "uncomfortable", pts: 2, min: 120 },
    lines: [">你同学考了那个注册什么师。", "爸，我现在上班都顾不上。", ">年轻人要多学东西。", "我白天学客户，晚上学怎么活下去。", ">别顶嘴，我是为你好。", "我知道，我知道。"] },
  { title: "爸爸问我工资多少", mood: { name: "被查户口", emo: "uncomfortable", pts: 2, min: 120 },
    lines: [">你一个月挣多少钱？", "爸，这个怎么说呢。", ">我就问问，隔壁老王问我。", "那你告诉他‘够花’。", ">不行，他会说我女儿不行。", "那就说‘很好’，别说数字。"] },
  { title: "爸爸催我找对象", mood: { name: "催婚压力", emo: "uncomfortable", pts: 2, min: 150 },
    lines: [">有没有谈对象啊？", "没有，爸。", ">你妈说，你别太挑。", "我没挑，是没人挑我。", ">那我让老张给你介绍。", "爸！上次老张介绍的那个都说我像他妈。"] },
  { title: "爸爸问我租房押金", mood: { name: "押金紧张", emo: "tense", pts: 2, min: 150 },
    lines: [">你租的房子，押金退了没？", "还没，房东说要验房。", ">有没有拍照留证据？", "拍了，但是不知道有没有用。", ">拍的时间、地点都写上。", "好，我等下就整理。"] },
  { title: "爸爸半夜打了三个电话", mood: { name: "虚惊一场", emo: "scared", pts: 3, min: 120 },
    lines: ["爸，怎么了？这么晚打三个电话。", ">没事没事，就是睡不着。", "你吓死我了，我以为出事了。", ">我手机上调错了，不是故意的。", "下次先发个消息。", ">好，我先发个‘嗯’。"] },
  { title: "爸爸说头有点晕", mood: { name: "放心不下", emo: "scared", pts: 3, min: 210 },
    lines: [">我这两天头有点晕。", "晕多久了？", ">就两天，没事。", "你去医院看了吗？", ">看啥，歇歇就好。", "不行，明天必须去，我给你预约。"] },
  { title: "我和爸爸为转账吵架", mood: { name: "一言不合", emo: "angry", pts: 2, min: 150 },
    lines: [">钱收到了没？", "爸，我说了不用转。", ">你就拿着，别嘴硬。", "我自己有工资，我养得起自己。", ">你养得起？你上次都吃泡面。", "那也是我自己的泡面！"] },
  { title: "我对爸爸发了脾气", mood: { name: "说重了话", emo: "angry", pts: 2, min: 210 },
    lines: [">你什么时候回家？", "我忙，别老问我。", ">我就问问，你妈想你。", "又是我妈，你自己就不想？", ">……", "算了，我挂了。"] },
  { title: "爸爸误读了我的朋友圈", mood: { name: "社死现场", emo: "embarrassed", pts: 2, min: 150 },
    lines: [">你那条状态，‘今天又被生活暴击’。", "爸，你看到了？", ">我给你点了赞，还评论了。", "你评论了什么？", ">‘打回去！’", "全公司都看到了，爸。"] },
  { title: "爸爸在地铁里喊我名字", mood: { name: "尴尬癌", emo: "embarrassed", pts: 2, min: 120 },
    lines: ["爸，我在地铁里，小声点。", ">什么？你声音太小了。", "我说我在地铁里！", ">你地铁里为什么不接我的电话？", "我现在不就接了吗？", ">全车人都听见我说‘乖女儿’了。"] },
  { title: "和爸爸无话可说", mood: { name: "尬聊时刻", emo: "bored", pts: 1, min: 90 },
    lines: [">吃了吗？", "吃了。", ">天气怎么样？", "还行。", ">哦，那没事了。", "嗯，那我挂了。"] },
  { title: "爸爸念了十分钟天气", mood: { name: "天气预报", emo: "bored", pts: 1, min: 90 },
    lines: [">明天局部有雨，后天转晴。", "嗯。", ">周末有冷空气。", "嗯。", ">你那边有没有降温？", "爸，我这边是室内。"] },
  { title: "爸爸说了句没头没脑的话", mood: { name: "发懵了", emo: "dazed", pts: 2, min: 90 },
    lines: [">我昨天梦到你变成了一条鱼。", "什么鱼？", ">大黄鱼，我钓上来又放了。", "为什么放了？", ">你对我说‘爸，放了我’。", "我听着怎么有点毛骨悚然。"] },
  { title: "爸爸问我算法是啥", mood: { name: "越讲越糊涂", emo: "dazed", pts: 2, min: 120 },
    lines: [">你们说的算法，是个啥？", "就是一套规则。", ">跟象棋规则一样？", "有点像，但是它自己会学。", ">它会自己下棋？", "也不全是……算了，爸你明白就好。"] },
  { title: "爸爸陪我修坏掉的水龙头", mood: { name: "合力修好", emo: "focused", pts: 2, min: 210 },
    lines: ["爸，我水龙头一直滴水。", ">先关总阀，看看有没有扳手。", "有，是你寄来的那把。", ">把螺母拧下来，看垫圈。", "垫圈裂了。", ">换个新的，我告诉你型号。"] },
  { title: "一起核对了报税表格", mood: { name: "一起报税", emo: "focused", pts: 2, min: 180 },
    lines: ["爸，个税这个表我看不懂。", ">念给我听，哪一栏？", "专项附加扣除。", ">租房那项填了吗？", "填了。", ">赡养老人那项，写我的名字。", "爸，谢谢你。"] },
  { title: "爸爸在电话里讲鱼线", mood: { name: "鱼线教学", emo: "focused", pts: 1, min: 120 },
    lines: ["爸，鱼线老是缠在一起怎么办？", ">先别急，慢慢理。", "我已经理了一小时了。", ">那就别理了，剪了重来。", "可它是新的。", ">新的也剪，人比线重要。"] },
]
